	@Test
	void reducerLawsDescribeExactMembershipWeightAndOrderingAcrossDemandClones() {
		AggregateSpec sample = AggregateSpec.slot("sample", 1, true, AggKind.SAMPLE);
		assertEquals(NativeReducerCapabilities.MergeLaw.ELIGIBLE_SAMPLE, sample.reducer.mergeLaw);
		assertEquals(NativeReducerCapabilities.Membership.NONE, sample.reducer.membership);
		assertFalse(sample.reducer.weightSensitive);
		assertTrue(sample.reducer.canReorderInput());
		AggregateSpec sum = AggregateSpec.slot("sum", 1, false, AggKind.SUM);
		assertTrue(sum.reducer.canFoldWeight(SimpleValueFactory.getInstance().createLiteral(7L), false));
		assertFalse(sum.reducer.canFoldWeight(SimpleValueFactory.getInstance().createLiteral(1D), false));
		assertFalse(sum.reducer.canFoldWeight(SimpleValueFactory.getInstance().createLiteral(1F), false));
		assertTrue(sum.reducer.canFoldWeight(SimpleValueFactory.getInstance().createLiteral("type error"), false));
		assertTrue(sum.reducer.requiresEncounterReplay);
		AggregateSpec concat = AggregateSpec.groupConcat("text", 1, true, "\ud83d\ude00");
		assertEquals(NativeReducerCapabilities.Membership.RDF_TERM, concat.reducer.membership);
		assertFalse(concat.reducer.canFoldWeight(SimpleValueFactory.getInstance().createLiteral("x"), false));
		assertTrue(concat.reducer.canFoldWeight(SimpleValueFactory.getInstance().createLiteral("x"), true));
		AggregateSpec length = concat.withResultDemand(NativeAggregateResultDemand.LEXICAL_LENGTH).withPositionMask(0);
		assertEquals(NativeReducerCapabilities.MergeLaw.LEXICAL_LENGTH, length.reducer.mergeLaw);
		assertEquals(NativeReducerCapabilities.Membership.RDF_TERM, length.reducer.membership);
		assertTrue(length.reducer.canReorderInput());
		assertTrue(length.reducer.supportsMarginal());
		assertEquals(1, length.separatorCodePoints);
		assertEquals(concat.name, length.name);
		assertEquals(concat.slot, length.slot);
		assertEquals(concat.separator, length.separator);
		AggregateSpec mapping = AggregateSpec.starDistinct("rows", new int[] { 0, 1 });
		assertEquals(NativeReducerCapabilities.Membership.VISIBLE_MAPPING, mapping.reducer.membership);
		assertFalse(mapping.reducer.supportsMarginal());
		AggregateSpec custom = AggregateSpec.custom("custom", mock(NativeCustomAggregate.class));
		assertEquals(NativeReducerCapabilities.MergeLaw.OPAQUE, custom.reducer.mergeLaw);
		assertFalse(custom.reducer.canFoldWeight(SimpleValueFactory.getInstance().createLiteral(1L), true));
		assertFalse(custom.reducer.supportsMarginal());
	}

	@Test
	void generatedInputsAndFinalPayloadsSpillInTheSameQueryLedgerAndReleaseOnClose() {
		String previousGroup = System.getProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY);
		String previousRuntime = System.getProperty(NativeRuntimeValueTable.MAX_BYTES_PROPERTY);
		LmdbQueryMemoryManager previousManager = LmdbNativeHashJoin.queryMemoryOverride;
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(128L << 10, 128L << 10);
		System.setProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY, "16384");
		System.setProperty(NativeRuntimeValueTable.MAX_BYTES_PROPERTY, "32768");
		LmdbNativeHashJoin.queryMemoryOverride = manager;
		SyntheticValueSource source = SyntheticValueSource.forEvaluation(source());
		AggregateSpec[] specs = { AggregateSpec.star("count"),
				AggregateSpec.slot("sample", 1, false, AggKind.SAMPLE),
				AggregateSpec.groupConcat("all", 1, false, "|") };
		NativeGroupIteration iteration = new NativeGroupIteration(source, SlotPlan.empty(), layout(), new int[] { 0 },
				specs, true, EmptyBindingSet.getInstance(), null, null, false, null);
		AggContext context = new AggContext(source, true);
		long created = NativeRuntimeValueSpill.CREATED.get(), deleted = NativeRuntimeValueSpill.DELETED.get();
		try (NativeGroupTable table = NativeGroupTable.create(new int[] { 0 }, specs, context,
				AggregateDistinctChannels.allHash(specs), true, false)) {
			RowState row = row(source);
			for (int index = 0; index < 256; index++) {
				int mark = row.mark();
				long group = source.executionContext()
						.internGeneratedKey(
								SimpleValueFactory.getInstance().createLiteral("group-" + index % 32));
				long value = source.executionContext().internGeneratedKey(payload("payload", index));
				assertTrue(row.bind(0, group));
				assertTrue(row.bind(1, value));
				table.add(row);
				row.rollback(mark);
				assertTrue(manager.usedBytes() <= manager.perQueryMaxBytes());
				assertTrue(source.executionContext().queryRuntimeValueAccountedBytes() <= 32768L,
						"input authority and reducer payload catalog share a single runtime budget");
			}
			assertTrue(NativeRuntimeValueSpill.CREATED.get() > created,
					"source payloads must spill before finalization");
			List<BindingSet> results = table.results(iteration, LmdbNativeAttemptMetrics.root());
			assertEquals(32, results.size());
			BindingSet first = results.getFirst();
			assertEquals(SimpleValueFactory.getInstance().createLiteral("group-0"), first.getValue("group"));
			assertEquals(8L, ((Literal) first.getValue("count")).longValue());
			String expected = IntStream.range(0, 8)
					.mapToObj(i -> payload("payload", i * 32).stringValue())
					.collect(Collectors.joining("|"));
			assertEquals(expected, first.getValue("all").stringValue());
			assertEquals(payload("payload", 0), first.getValue("sample"));
			assertTrue(manager.usedBytes() > 0L,
					"the accepted result replay and original authority still own resources");
			assertTrue(manager.usedBytes() <= manager.perQueryMaxBytes());
		} finally {
			iteration.close();
			context.close();
			source.executionContext().close();
			LmdbNativeHashJoin.queryMemoryOverride = previousManager;
			restore(NativeCountGroupStore.MAX_BYTES_PROPERTY, previousGroup);
			restore(NativeRuntimeValueTable.MAX_BYTES_PROPERTY, previousRuntime);
		}
		assertEquals(0L, manager.usedBytes());
		assertEquals(NativeRuntimeValueSpill.CREATED.get() - created, NativeRuntimeValueSpill.DELETED.get() - deleted,
				"both original and child payload owners must release every spill file");
	}

